mapper.select:
/* isry.itgcm.casemng.uneart.DscsnUneartMapper.selectUneartDscsnList(발굴목록조회) YOO.CHI.HOON*/
/* 발굴(초기상담) 내역 */ T21.ERYY_DSCSN_NO AS DSCSN_NO -- 초기상담번호(ER) , T21.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD -- 단위업무구분코드 , T21.CONSTT_NO AS CONSTT_NO -- 상담자번호 , ( SELECT C##RG.DEC_B64(X.FLNM_ENCPT) FROM SCA100 X WHERE X.ENFSN_NO = T21.CONSTT_NO ) AS CONSTT_NM -- 상담자명암호화 , T21.DSCSN_YMD AS DSCSN_YMD -- 상담일자 , T21.DSCSN_BGNG_HR AS DSCSN_BGNG_HR -- 상담시작시간 , T21.DSCSN_END_HR AS DSCSN_END_HR -- 상담종료시간 , T21.DSCSN_COURS_SE_CD AS DSCSN_COURS_SE_CD -- 상담경로구분코드 , T21.DSCSN_PRCS_HISTB_SE_CD AS DSCSN_PRCS_HISTB_SE_CD -- 상담처리내역구분코드 , T21.DSCSN_TTL_NM AS DSCSN_TTL_NM -- 상담제목명 , T21.DSCSN_CN AS DSCSN_CN -- 상담내용 , T21.CONSTT_INST_NO AS CONSTT_INST_NO -- 상담자기관번호 , ( SELECT X.INST_NM FROM SAA000 X WHERE X.INST_NO = T21.CONSTT_INST_NO ) AS CONSTT_INST_NM -- 상담자기관명 , T21.RQST_TRGT_INST_NO AS RQST_TRGT_INST_NO -- 의뢰대상기관번호 , ( SELECT X.INST_NM FROM SAA000 X WHERE X.INST_NO = T21.RQST_TRGT_INST_NO ) AS RQST_TRGT_INST_NM -- 의뢰대상기관명 , ( SELECT T31.TRPR_INFO_NO AS TRPR_INFO_NO FROM SEA110 T31 /* 상담후조치 */ WHERE T31.ERYY_DSCSN_NO = T21.ERYY_DSCSN_NO AND T31.ACTN_SN = ( SELECT MIN(T41.ACTN_SN) FROM SEA110 T41 /* 상담후조치 */ WHERE T41.ERYY_DSCSN_NO = T21.ERYY_DSCSN_NO AND T41.DEL_YN = 'N' ) ) AS TRPR_INFO_NO -- 대상자정보번호(TR) , ( SELECT CASE WHEN COUNT(*) > 0 THEN COUNT(*) ELSE 0 END TRPR_CNT FROM SEA110 T31 /* 상담후조치 */ WHERE T31.ERYY_DSCSN_NO = T21.ERYY_DSCSN_NO AND T31.DEL_YN = 'N' AND EXISTS (SELECT 'X' FROM SEA110 T41 /* 상담후조치 */ WHERE T41.ERYY_DSCSN_NO = T21.ERYY_DSCSN_NO ) ) AS TRPR_INFO_NO_CNT -- (발굴상담,아웃리치)대상자건수(목록표기) , ( SELECT C##RG.DEC_B64(T31.TRPR_NM_ENCPT) AS TRPR_NM_ALL FROM ( SELECT T41.ERYY_DSCSN_NO AS ERYY_DSCSN_NO , T41.TRPR_INFO_NO AS TRPR_INFO_NO , CASE WHEN T42.INDV_IDNTFC_NO IS NOT NULL THEN NVL(T43.FLNM_ENCPT, T42.TRPR_NM_ENCPT) ELSE T42.TRPR_NM_ENCPT END AS TRPR_NM_ENCPT -- 대상자명 FROM SEA110 T41 /* 상담후조치 */ , SEA200 T42 /* 대상자정보 */ , SCA300 T43 /* 개인정보 */ WHERE T41.ERYY_DSCSN_NO = T21.ERYY_DSCSN_NO AND T41.DEL_YN = 'N' AND T41.TRPR_INFO_NO = T42.TRPR_INFO_NO (+) AND T42.INDV_IDNTFC_NO = T43.INDV_IDNTFC_NO (+) -- 개인식별번호 AND ROWNUM = 1 ) T31 ) AS TRPR_NM -- 대상자명암호화 , '01' AS UNEART_TYPE_SE_CD -- 발굴유형구분코드(01:발굴) FROM SEA100 T21 /* 초기상담 */ WHERE 1 = 1 AND T21.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} -- 단위업무구분코드 AND T21.DSCSN_YMD BETWEEN #{UNEART_BGNG_YMD} -- 발굴시작일자 AND #{UNEART_END_YMD} -- 발굴종료일자
/* 20230203_유치훈_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230203_유치훈_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
AND T21.DSCSN_COURS_SE_CD = #{DSCSN_COURS_SE_CD} -- 상담경로구분코드
AND T21.DSCSN_TTL_NM LIKE '%' || #{DSCSN_TTL_NM} || '%' -- 상담제목
AND T21.ERYY_DSCSN_NO IN ( SELECT T1.ERYY_DSCSN_NO AS ERYY_DSCSN_NO /* 초기상담번호*/ FROM SEA110 T1 /*상담후조치*/ INNER JOIN SEA200 T2 /* 대상자정보*/ ON (T1.TRPR_INFO_NO = T2.TRPR_INFO_NO) WHERE 1 = 1 AND EXISTS ( SELECT 'X' FROM SEA100 X /* 초기상담*/ WHERE X.ERYY_DSCSN_NO = T1.ERYY_DSCSN_NO) AND T1.DEL_YN = 'N' AND T2.TRPR_NM_ENCPT = (C##RG.ENC_B64(#{TRPR_NM})) /* 대상자명*/ AND T2.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} /* 단위업무구분코드*/ GROUP BY T1.ERYY_DSCSN_NO )
AND T21.CONSTT_NO IN ( SELECT X.ENFSN_NO FROM SCA100 X WHERE X.ENFSN_NO = T21.CONSTT_NO AND X.FLNM_ENCPT = (C##RG.ENC_B64(#{CONSTT_NM})) -- 상담자명암호화 )
AND T21.CONSTT_INST_NO = #{CONSTT_INST_NO} -- 상담자기관번호
ORDER BY T21.FRST_REG_DT DESC

/* 아웃리치(집단상담) 내역 */ T21.ERYY_GR_DSCSN_NO AS DSCSN_NO -- 초기집단상담번호 , T21.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD -- 단위업무구분코드 , T21.CONSTT_NO AS CONSTT_NO -- 상담자번호 , ( SELECT C##RG.DEC_B64(X.FLNM_ENCPT) FROM SCA100 X WHERE X.ENFSN_NO = T21.CONSTT_NO ) AS CONSTT_NM -- 상담자명암호화 , T21.DSCSN_YMD AS DSCSN_YMD -- 상담일자 , T21.UNEART_ACTVT_MTHD_SE_CD AS UNEART_ACTVT_MTHD_SE_CD -- (아웃리치) 발굴활동방법구분코드 , T21.ACTVT_TRGT_RGN_SGG_CD AS ACTVT_TRGT_RGN_SGG_CD -- (아웃리치) 활동대상지역시군구코드 , ( SELECT X.CTPV_NM || ' ' || X.SGG_NM FROM SAA020 X /* 시군구코드 */ WHERE X.SGG_CD = T21.ACTVT_TRGT_RGN_SGG_CD ) AS ACTVT_TRGT_RGN_SGG_NM -- (아웃리치) 활동대상지역시군구명 , T21.ACTVT_TRGT_RGN_DTL_PLACE_NM AS ACTVT_TRGT_RGN_DTL_PLACE_NM -- (아웃리치) 활동대상지역상세장소명 , (SELECT X.UNEART_ACTVT_CL_SE_CD FROM SEA140 X WHERE X.ERYY_GR_DSCSN_NO = T21.ERYY_GR_DSCSN_NO AND ROWNUM = 1) AS UNEART_ACTVT_CL_SE_CD -- (아웃리치) 발굴활동분류구분코드 , T21.RGTR_INST_NO AS CONSTT_INST_NO -- 등록자기관번호 , ( SELECT X.INST_NM FROM SAA000 X WHERE X.INST_NO = T21.RGTR_INST_NO ) AS CONSTT_INST_NM -- 등록자기관명 , T21.DSCSN_BGNG_HR AS DSCSN_BGNG_HR -- 상담시작시간 , T21.DSCSN_END_HR AS DSCSN_END_HR -- 상담종료시간 , T21.DSCSN_TTL_NM AS DSCSN_TTL_NM -- 상담제목명 , T21.DSCSN_CN AS DSCSN_CN -- 상담내용 , ( SELECT T31.TRPR_INFO_NO AS TRPR_INFO_NO FROM SEA130 T31 /* 집단상담후조치 */ WHERE T31.ERYY_GR_DSCSN_NO = T21.ERYY_GR_DSCSN_NO AND T31.ACTN_SN = ( SELECT MIN(T41.ACTN_SN) FROM SEA130 T41 /* 집단상담후조치 */ WHERE T41.ERYY_GR_DSCSN_NO = T21.ERYY_GR_DSCSN_NO AND T41.DEL_YN = 'N' ) ) AS TRPR_INFO_NO -- 대상자정보번호(TR) , ( SELECT CASE WHEN COUNT(*) > 0 THEN COUNT(*) ELSE 0 END TRPR_CNT FROM SEA130 T31 /* 상담후조치 */ WHERE T31.ERYY_GR_DSCSN_NO = T21.ERYY_GR_DSCSN_NO AND T31.DEL_YN = 'N' AND EXISTS (SELECT 'X' FROM SEA130 T41 /* 상담후조치 */ WHERE T41.ERYY_GR_DSCSN_NO = T21.ERYY_GR_DSCSN_NO
) ) AS TRPR_INFO_NO_CNT -- (발굴상담,아웃리치)대상자건수(목록표기) , ( SELECT C##RG.DEC_B64(T31.TRPR_NM_ENCPT) AS TRPR_NM_ALL FROM ( SELECT T41.ERYY_GR_DSCSN_NO AS ERYY_GR_DSCSN_NO , T41.TRPR_INFO_NO AS TRPR_INFO_NO , CASE WHEN T42.INDV_IDNTFC_NO IS NOT NULL THEN NVL(T43.FLNM_ENCPT, T42.TRPR_NM_ENCPT) ELSE T42.TRPR_NM_ENCPT END AS TRPR_NM_ENCPT -- 대상자명 FROM SEA130 T41 /* 집단상담후조치 */ , SEA200 T42 /* 대상자정보 */ , SCA300 T43 /* 개인정보 */ WHERE T41.ERYY_GR_DSCSN_NO = T21.ERYY_GR_DSCSN_NO AND T41.DEL_YN = 'N' AND T41.TRPR_INFO_NO = T42.TRPR_INFO_NO (+) AND T42.INDV_IDNTFC_NO = T43.INDV_IDNTFC_NO (+) -- 개인식별번호 AND ROWNUM = 1 ) T31 ) AS TRPR_NM -- 대상자명암호화 , '02' AS UNEART_TYPE_SE_CD -- 발굴유형구분코드(02:아웃리치) FROM SEA120 T21 /* 초기집단상담 */ WHERE 1 = 1 AND T21.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} -- 단위업무구분코드 AND T21.DSCSN_YMD BETWEEN #{UNEART_BGNG_YMD} -- 발굴시작일자 AND #{UNEART_END_YMD} -- 발굴종료일자 /* 20230203_유치훈_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230203_유치훈_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
AND T21.UNEART_ACTVT_MTHD_SE_CD = #{UNEART_ACTVT_MTHD_SE_CD} -- 발굴활동방법구분코드
AND T21.ACTVT_TRGT_RGN_SGG_CD = #{ACTVT_TRGT_RGN_SGG_CD} -- 활동대상지역시군구코드
AND T21.ERYY_GR_DSCSN_NO IN ( SELECT T1.ERYY_GR_DSCSN_NO AS ERYY_GR_DSCSN_NO /* 초기집단상담번호*/ FROM SEA130 T1 /*집단상담후조치*/ INNER JOIN SEA200 T2 /* 대상자정보*/ ON (T1.TRPR_INFO_NO = T2.TRPR_INFO_NO) WHERE 1 = 1 AND EXISTS ( SELECT 'X' FROM SEA120 X WHERE X.ERYY_GR_DSCSN_NO = T1.ERYY_GR_DSCSN_NO) AND T1.DEL_YN = 'N' AND T2.TRPR_NM_ENCPT = (C##RG.ENC_B64(#{TRPR_NM})) /* 대상자명*/ AND T2.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} /* 단위업무구분코드*/ GROUP BY T1.ERYY_GR_DSCSN_NO )
AND T21.CONSTT_NO IN ( SELECT X.ENFSN_NO FROM SCA100 X WHERE X.ENFSN_NO = T21.CONSTT_NO AND X.FLNM_ENCPT = (C##RG.ENC_B64(#{CONSTT_NM})) -- 상담자명암호화 )
AND T21.RGTR_INST_NO = #{CONSTT_INST_NO} -- 상담자기관번호
ORDER BY T21.FRST_REG_DT DESC

/* 긴급개입 내역 */ T21.EMRG_INTRVN_NO AS DSCSN_NO -- 긴급개입번호 , T21.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD -- 단위업무구분코드 , T21.CONSTT_NO AS CONSTT_NO -- 상담자번호 , ( SELECT C##RG.DEC_B64(X.FLNM_ENCPT) FROM SCA100 X WHERE X.ENFSN_NO = T21.CONSTT_NO ) AS CONSTT_NM -- 상담자명암호화 , T21.RCPT_YMD AS DSCSN_YMD -- 조치일자 , (SELECT X.EMRG_INTRVN_ACTN_SE_CD FROM SEA270 X WHERE X.EMRG_INTRVN_NO = T21.EMRG_INTRVN_NO AND ROWNUM = 1) AS EMRG_INTRVN_ACTN_SE_CD -- (긴급개입) 긴급개입조치구분코드 , (SELECT X.EMRG_INTRVN_OUTSD_LINK_SE_CD FROM SEA270 X WHERE X.EMRG_INTRVN_NO = T21.EMRG_INTRVN_NO AND ROWNUM = 1) AS EMRG_INTRVN_OUTSD_LINK_SE_CD -- (긴급개입) 긴급개입외부연계구분코드 , T21.CONSTT_INST_NO AS CONSTT_INST_NO -- 상담자기관번호 , ( SELECT X.INST_NM FROM SAA000 X WHERE X.INST_NO = T21.CONSTT_INST_NO ) AS CONSTT_INST_NM -- 상담자기관명 , T21.RCPT_HR AS DSCSN_BGNG_HR -- 처리시간 , T21.RCPT_HR AS DSCSN_END_HR -- 조치시간 , T21.DCLR_TTL_NM AS DSCSN_TTL_NM -- 신고제목명 , T21.DCLR_CN AS DSCSN_CN -- 신고내용 , T21.TRPR_INFO_NO AS TRPR_INFO_NO -- 대상자정보번호(TR) , ( SELECT C##RG.DEC_B64(X.TRPR_NM_ENCPT) FROM SEA200 X WHERE X.TRPR_INFO_NO = T21.TRPR_INFO_NO ) AS TRPR_NM -- 대상자명암호화 , 0 AS TRPR_INFO_NO_CNT -- (발굴상담,아웃리치)대상자건수(목록표기) , '03' AS UNEART_TYPE_SE_CD -- 발굴유형구분코드(03:긴급개입) FROM SEA220 T21 /* 긴급개입 */ WHERE 1 = 1 AND T21.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} -- 단위업무구분코드 AND T21.DEL_YN = 'N' AND T21.FRST_REG_DT BETWEEN TO_DATE(#{UNEART_BGNG_YMD} || '000000', 'YYYYMMDDHH24MISS') -- 발굴시작일자 AND TO_DATE(#{UNEART_END_YMD} || '235959', 'YYYYMMDDHH24MISS') -- 발굴종료일자
/* 20230203_유치훈_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230203_유치훈_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
AND T21.TRPR_INFO_NO IN ( SELECT F.TRPR_INFO_NO FROM SEA200 F WHERE F.TRPR_INFO_NO = T21.TRPR_INFO_NO AND F.TRPR_NM_ENCPT = (C##RG.ENC_B64(#{TRPR_NM})) ) -- 대상자명암호화
AND T21.CONSTT_NO IN ( SELECT X.ENFSN_NO FROM SCA100 X WHERE X.ENFSN_NO = T21.CONSTT_NO AND X.FLNM_ENCPT = (C##RG.ENC_B64(#{CONSTT_NM})) -- 상담자명암호화 )
AND T21.CONSTT_INST_NO = #{CONSTT_INST_NO} -- 상담자기관번호
AND T21.DCLR_TTL_NM LIKE '%' || #{DCLR_TTL_NM} || '%' -- 접수제목
ORDER BY T21.FRST_REG_DT DESC
